package com.ukkera.pos.security

import com.ukkera.pos.types.Revision
import kotlin.test.*
import kotlinx.coroutines.test.runTest

/** Synthetic secrets/identities only; neither native timing nor platform custody qualification. */
class LocalAccessSecretVerificationTest {
    @Test fun matchesLiteralIndependentDomainSeparatedVector() {
        // Literal Python hashlib vector; not generated by the function under test.
        val hash = LocalAccessTokenHash.fromCanonicalSha256(
            "208bd4c0ca7941f488f90770a84f24472cf47d0e2b980f400b26ba718b32a0bb")
        assertTrue(hash.matchesSecret(ByteArray(32) { it.toByte() }))
        assertFalse(hash.matchesSecret(ByteArray(32)))
    }

    @Test fun everySecretByteIsSignificantAndCallerBuffersStayUnchanged() {
        val secret = ByteArray(32) { (it + 41).toByte() }
        val original = secret.copyOf()
        val hash = LocalAccessTokenHash.hashSecret(secret)
        repeat(32) { index ->
            val changed = original.copyOf().also { it[index] = (it[index].toInt() xor 1).toByte() }
            val before = changed.copyOf()
            assertFalse(hash.matchesSecret(changed), "secret byte $index")
            assertContentEquals(before, changed)
        }
        assertTrue(hash.matchesSecret(secret)); assertContentEquals(original, secret)
    }

    @Test fun everyDigestByteIsSignificantInTheFixedSizePrimitive() {
        val left = ByteArray(32) { (it * 3).toByte() }
        assertTrue(equalLocalAccessDigests(left, left.copyOf()))
        repeat(32) { index ->
            val right = left.copyOf().also { it[index] = (it[index].toInt() xor 0x80).toByte() }
            val before = right.copyOf()
            assertFalse(equalLocalAccessDigests(left, right), "digest byte $index")
            assertContentEquals(before, right)
        }
        assertContentEquals(ByteArray(32) { (it * 3).toByte() }, left)
    }

    @Test fun primitiveRejectsAliasingAndEveryUnsupportedLengthBeforeNativeAccess() {
        val digest = ByteArray(32)
        assertFailsWith<IllegalArgumentException> { equalLocalAccessDigests(digest, digest) }
        for (length in listOf(0, 1, 16, 31, 33, 64, 8192)) {
            assertFailsWith<IllegalArgumentException> { equalLocalAccessDigests(digest, ByteArray(length)) }
            assertFailsWith<IllegalArgumentException> { equalLocalAccessDigests(ByteArray(length), digest) }
        }
    }

    @Test fun secretHelperRequiresExactProfileInsteadOfTruncationOrPadding() {
        val hash = LocalAccessTokenHash.hashSecret(ByteArray(32))
        for (length in listOf(0, 1, 16, 31, 33, 64, 8192)) {
            val secret = ByteArray(length) { 42 }
            val before = secret.copyOf()
            val error = assertFailsWith<IllegalArgumentException> { hash.matchesSecret(secret) }
            assertNull(error.cause); assertContentEquals(before, secret)
            assertFalse(hash.canonicalSha256() in error.toString())
        }
    }

    @Test fun identityOverloadAndExistingPrincipalPredicateAgreeForValidAndInvalidFacts() = runTest {
        val identity = VerifiedLocalIdentity(id(4), branch, id(6), id(7), SessionGeneration(1), Revision(0),
            AuthenticationPurpose.INTERACTIVE)
        val principal = assertNotNull(TrustedPrincipalFactory(object : PrincipalVerifier by DenyAllPrincipalVerifier {
            override suspend fun verifyLocal(credentials: LocalGatewayCredentials): VerifiedLocalIdentity = identity
        }).authenticateLocal(LocalGatewayCredentials(id(8), OpaqueCredential(ByteArray(32)))))
        val issuance = LocalAccessIssuance(branch, id(4), id(7), id(6), SessionGeneration(1), Revision(0),
            Revision(0), id(9), MonotonicMoment(id(10), 100), 50, LocalAccessTokenHash.hashSecret(ByteArray(32)))
        val admission = LocalDeviceAdmission(branch, id(6), Revision(0), true, "synthetic-key", null, emptySet())
        for (enabled in listOf(true, false)) for (present in listOf(true, false)) {
            for (status in SessionStatus.entries) for (time in listOf(99L, 100L, 149L, 150L)) {
                if (!enabled && status == SessionStatus.ACTIVE) continue // Structurally forbidden state.
                val state = LocalAccountSessionState(branch, id(4), enabled, Revision(0), SessionGeneration(1),
                    listOf(LocalSessionRecord(id(7), branch, id(4), id(6), SessionGeneration(1), status,
                        AuthenticationPurpose.INTERACTIVE)))
                val expected = enabled && present && status == SessionStatus.ACTIVE && time in 100L..149L
                val candidateResult = LocalAccessEligibility.matchesCurrentFacts(identity, issuance, state,
                    Revision(0), present, admission, id(9), MonotonicMoment(id(10), time))
                assertEquals(expected, candidateResult)
                assertEquals(candidateResult, LocalAccessEligibility.matchesCurrentFacts(principal, issuance, state,
                    Revision(0), present, admission, id(9), MonotonicMoment(id(10), time)))
            }
        }
    }
}
